INSERT INTO advertisement (
    center_no, ad_title, ad_content, start_date, end_date, partner_id, ad_type, target_keyword, ad_status, bid_price
) VALUES (
    #{centerNo}, #{adTitle}, #{adContent}, NOW(), DATE_ADD(NOW(), INTERVAL #{durationDays} DAY), 
    #{partnerId}, #{adType}, #{targetKeyword}, 0, #{paymentAmount}
)

mapper.select:
SELECT 
    /* 1. 정액제(CPT) 요약: 배너형은 보통 정액제 */
    (SELECT IFNULL(SUM(bid_price), 0) FROM advertisement WHERE partner_id = #{partnerId} AND (billing_model = 'CPT' OR ad_type LIKE '%배너%')) as cptPrice,
    (SELECT COUNT(*) FROM advertisement WHERE partner_id = #{partnerId} AND (billing_model = 'CPT' OR ad_type LIKE '%배너%') AND ad_status = 1) as cptActiveCount,

    /* 2. 종량제(CPC) 요약: 상위노출은 보통 종량제 */
    (SELECT IFNULL(SUM(remaining_budget), 0) FROM advertisement WHERE partner_id = #{partnerId} AND (billing_model = 'CPC' OR ad_type LIKE '%상위%')) as cpcBudget,
    (SELECT COUNT(*) FROM advertisement WHERE partner_id = #{partnerId} AND (billing_model = 'CPC' OR ad_type LIKE '%상위%') AND ad_status = 1) as cpcActiveCount,

    /* 3. 배너형 성과 (누적) */
    (SELECT COUNT(*) FROM ad_impression WHERE ad_id IN (SELECT ad_id FROM advertisement WHERE partner_id = #{partnerId} AND ad_type LIKE '%배너%')) as bannerImp,
    (SELECT COUNT(*) FROM ad_click WHERE ad_id IN (SELECT ad_id FROM advertisement WHERE partner_id = #{partnerId} AND ad_type LIKE '%배너%')) as bannerClick,

    /* 4. 상위노출형 성과 (누적) */
    (SELECT COUNT(*) FROM ad_impression WHERE ad_id IN (SELECT ad_id FROM advertisement WHERE partner_id = #{partnerId} AND ad_type LIKE '%상위%')) as keywordImp,
    (SELECT COUNT(*) FROM ad_click WHERE ad_id IN (SELECT ad_id FROM advertisement WHERE partner_id = #{partnerId} AND ad_type LIKE '%상위%')) as keywordClick
